SELECT * FROM (SELECT "first_name", "last_name" FROM "performances" JOIN "salaries" ON "salaries"."player_id" = "performances"."player_id" AND "salaries"."year" = "performances"."year" JOIN "players" ON "players"."id" = "performances"."player_id" WHERE "H" IS NOT 0 AND "salaries"."year" = 2001 ORDER BY "salary"/"H" ASC, "first_name", "last_name" LIMIT 10) INTERSECT SELECT * FROM (SELECT "first_name", "last_name" FROM "performances" JOIN "salaries" ON "salaries"."player_id" = "performances"."player_id" AND "salaries"."year" = "performances"."year" JOIN "players" ON "players"."id" = "performances"."player_id" WHERE "RBI" IS NOT 0 AND "salaries"."year" = 2001 ORDER BY "salary"/"RBI" ASC, "first_name", "last_name" LIMIT 10) ORDER BY "last_name";
